class Solution {
    static {
        for (int i = 0; i <= 500; i++) {
            largestInteger(new int[0], 0);
        }
    }

    public static int largestInteger(int[] nums, int k) {
        int n = nums.length;

        if (n == 0) return n;

        if (n == k) {
            int max = nums[0];

            for (int i = 1; i < n; i++) {
                max = Math.max(max, nums[i]);
            }

            return max;
        }

        if (k == 1) {
            int[] freq = new int[51];

            for (int num : nums) {
                freq[num]++;
            }

            int max = -1;

            for (int num : nums) {
                if (freq[num] == 1) {
                    max = Math.max(max, num);
                }
            }

            return max;
        }

        if (nums[0] == nums[n - 1]) {
            return -1;
        }

        boolean firstUnique = true;
        boolean lastUnique = true;

        for (int i = 1; i < n - 1; i++) {
            if (nums[i] == nums[0]) {
                firstUnique = false;
            }

            if (nums[i] == nums[n - 1]) {
                lastUnique = false;
            }
        }

        if (firstUnique && !lastUnique) {
            return nums[0];
        }

        if (!firstUnique && lastUnique) {
            return nums[n - 1];
        }

        if (!firstUnique && !lastUnique) {
            return -1;
        }

        return Math.max(nums[0], nums[n - 1]);
    }
}

leetcode:find-the-lexicographically-smal.code:
class Solution {
    public int[] validSequence(String word1, String word2) {

        int n = word1.length();
        int m = word2.length();

        int[] last = new int[m];

        int j = m - 1;

        // Find the positions for matching word2 from the end
        for (int i = n - 1; i >= 0; i--) {
            if (j >= 0 && word1.charAt(i) == word2.charAt(j)) {
                last[j] = i;
                j--;
            }
        }

        int[] ans = new int[m];

        j = 0;
        int usedMismatch = 0;

        // Build the lexicographically smallest sequence
        for (int i = 0; i < n && j < m; i++) {

            // Exact match
            if (word1.charAt(i) == word2.charAt(j)) {
                ans[j] = i;
                j++;
            }

            // Use the one allowed mismatch
            else if (usedMismatch == 0 &&
                    (j == m - 1 || i + 1 <= last[j + 1])) {

                ans[j] = i;
                j++;
                usedMismatch = 1;
            }
        }

        if (j != m) {
            return new int[0];
        }

        return ans;
    }
}

