class Solution {
    public int maxSubarrayLength(int[] nums, int k) {
        int left = 0;
        int res = 0;

        Map<Integer, Integer> count = new HashMap<>();
        int n = nums.length;

        for (int i = 0; i < n; i++) {
            count.put(
                nums[i],
                count.getOrDefault(nums[i], 0) + 1
            );

            while (count.get(nums[i]) > k) {
                count.put(
                    nums[left],
                    count.get(nums[left]) - 1
                );

                left++;
            }

            res = Math.max(res, i - left + 1);
        }

        return res;
    }
}

leetcode:longest-palindromic-substring.code:
class Solution {
    private int expandFromCenter(String s, int left, int right) {
        while (left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) {
            left--;
            right++;
        }
        return right - left - 1;
    }

    public String longestPalindrome(String s) {
        int bestStart = 0;
        int bestLength = 1;
        for (int i = 0; i < s.length(); i++) {
            int oddLength = expandFromCenter(s, i, i);
            int evenLength = expandFromCenter(s, i, i + 1);
            int longer = Math.max(oddLength, evenLength);
            if (longer > bestLength) {
                bestLength = longer;
                bestStart = i - (longer - 1) / 2;
            }
        }
        return s.substring(bestStart, bestStart + bestLength);
    }
}

