class Solution {
    public boolean predictTheWinner(int[] nums) {
        int n = nums.length;
        if(n % 2 == 0) return true;
        int dp[] = nums.clone();
        for(int i = n - 2; i >= 0; i--) {
            for(int j = i + 1; j < n; j++) dp[j] = Math.max(nums[i] - dp[j], nums[j] - dp[j - 1]);
        }
        return dp[n - 1] >= 0;
    }
}

